<script setup>import{Link,router}from'@inertiajs/vue3';import{reactive}from'vue';import AppLayout from'../../Layouts/AppLayout.vue';import Pagination from'../../Components/Pagination.vue';import SeoHead from'../../Components/SeoHead.vue';const props=defineProps({services:Object,categories:Array,selectedCategory:Object,filters:Object}),f=reactive({...props.filters});const apply=()=>router.get('/services',f,{preserveState:true,replace:true});</script><template><AppLayout><SeoHead title="Technical services" description="Book electronics repair, computer support and network installation services from Prinx Electronics."/><div class="container-shell py-8"><p class="section-kicker">Prinx services</p><h1 class="section-title">{{selectedCategory?.name||'Professional technical services'}}</h1><div class="mt-5 flex gap-3"><input v-model="f.search" class="input max-w-md" placeholder="Search services" @keyup.enter="apply"><select v-model="f.category" class="input max-w-xs" @change="apply"><option value="">All services</option><option v-for="c in categories" :value="c.slug" :key="c.id">{{c.name}}</option></select></div><div class="mt-6 grid gap-4 md:grid-cols-2 lg:grid-cols-3"><Link v-for="s in services.data" :key="s.id" :href="`/services/${s.slug}`" class="card overflow-hidden"><img :src="s.image_url" :alt="s.name" class="aspect-[4/3] w-full object-cover"><div class="p-5"><p class="text-xs font-black uppercase text-prinx-600">{{s.category?.name}}</p><h2 class="mt-1 text-lg font-black">{{s.name}}</h2><p class="mt-2 text-sm text-slate-500">{{s.short_description}}</p><p class="mt-4 font-black">{{s.price_label||'Request a quote'}}</p></div></Link></div><Pagination :links="services.links"/></div></AppLayout></template>
